-- Hardwood Lab - seed_0028_restoration_academy_scouting.sql
--
-- The Restoration Academy scouting note for the Nov 17, 2026 game, built from
-- Matt own scouting notes: tip, half-court and full-court defense, offense,
-- BLOB offense and defense, the two players to know (#2 and #22), plus the
-- drawn diagrams. The game plan lines, the two player "how we guard him"
-- lines and the Box BLOB drawing are drafted from those notes - edit any of
-- them in the app (Teams > Scouting > Restoration Academy).
--
-- Needs no migration: it only fills the existing notes jsonb column.
-- Safe to re-run: it inserts only if the team has no note for this opponent.
--
-- Run this in the Supabase SQL editor.
--
-- Dollar quoting, no apostrophes in comments: see seed_0005.
-- ============================================================================

do $body$
declare
  target_team_id uuid;
begin
  select id into target_team_id
  from hoops.teams
  where name ilike $gm$Evangel JV Boys$gm$;

  if target_team_id is null then
    raise exception $gm$No team named "Evangel JV Boys" found in hoops.teams - check the exact name and edit this script to match.$gm$;
  end if;

  insert into hoops.scouting_notes (team_id, opponent_name, notes)
  select target_team_id, $gm$Restoration Academy$gm$, $rj${"v":2,"gameDate":"2026-11-17","headline":"Presses full court, extends their zones, runs a high ball screen and leaks out on every miss.","tip":"They tip it backwards, which feeds perfectly into our offensive tip.","defense_half":"1-2-2 extended zone: trap the corners.\n2-3 zone: mostly on BLOB defense.\n2-2-1: fully extends in half court and leaves the three-point line open for an easy pass, then a 2v1 against their back defender.","defense_full":"2-2-1 press on a made basket or a dead-ball out of bounds.\nTheir goal is to let you get it in low, not in the middle.\nBeat it by sending 2 deep: they come up tight in the backcourt and do not look behind themselves.","offense":"High ball screen. Look to shoot the 3 or penetrate.\nShooters in the corners and the opposite wing.\nThe screen usually comes from the big and he rolls. We must hedge, and be aggressive to anticipate the roll from the help side.\nThey leak out and take off on opponents' missed shots or turnovers.","blob_offense":"Line: our Stack play, outlet thrown to the top of the key.\nBox: pop corner from the post and inbound there. The elbow pops out for the pass. The corner big down-screens the inbounder to pop out for a pass to the corner 3.","blob_defense":"2-3 zone with three low defenders and no on-ball pressure. Covering the ball-side corner and the inside shot.\nBall-side elbow looks pretty open as the guards spread out a lot.","slob":"","personnel":"","game_plan":"Run our offensive tip. They tip it backwards, which feeds it perfectly.\nBeat the full-court 2-2-1: get it in low, then send 2 deep behind a press that is not looking.\nAgainst the 2-2-1 in the half court, hit the open three-point line and play 2v1 against their back defender. Against the 1-2-2, pass out of the corner before the trap closes.\nHedge hard on the high ball screen and be aggressive from the help side to anticipate the roll.\nGet back: they leak out on every missed shot and turnover.\nOn BLOB against their 2-3, attack the open ball-side elbow.","tendencies":"","players":[{"id":"p2","number":"2","name":"","label":"Best player","tendencies":"Obviously their best player. Wants to drive, and will take the 3 if given it.","plan":"Take the 3 away first, then build a wall against the drive. Do not give him a clean look."},{"id":"p22","number":"22","name":"","label":"Driver","tendencies":"Not a great shooter but really good at driving. Prefers a low pickup layup, also a high pickup.","plan":"Stay in front and make him shoot. Keep him off the rim."}],"diagrams":[{"id":"rest-d-122","section":"defense_half","title":"1-2-2 extended zone: trap the corners","caption":"","frames":[{"offense":[{"id":"O1","pos":{"x":25,"y":40}},{"id":"O2","pos":{"x":43,"y":22}},{"id":"O3","pos":{"x":7,"y":22}},{"id":"O4","pos":{"x":46,"y":5}},{"id":"O5","pos":{"x":4,"y":5}}],"defense":[{"id":"X1","man":"O1","coverage":"manual","manualPos":{"x":25,"y":35}},{"id":"X2","man":"O3","coverage":"manual","manualPos":{"x":11,"y":27}},{"id":"X3","man":"O2","coverage":"manual","manualPos":{"x":39,"y":27}},{"id":"X4","man":"O5","coverage":"manual","manualPos":{"x":17,"y":12}},{"id":"X5","man":"O4","coverage":"manual","manualPos":{"x":33,"y":12}}],"ballHolder":"O1","lines":[{"id":"rest1","type":"pass","color":"offense","points":[{"x":25,"y":40},{"x":43,"y":22}]}],"note":"Extended: the point picks up near half court, the wings sit above the arc, only two are left back."},{"offense":[{"id":"O1","pos":{"x":25,"y":40}},{"id":"O2","pos":{"x":43,"y":22}},{"id":"O3","pos":{"x":7,"y":22}},{"id":"O4","pos":{"x":46,"y":5}},{"id":"O5","pos":{"x":4,"y":5}}],"defense":[{"id":"X1","man":"O1","coverage":"manual","manualPos":{"x":29,"y":33}},{"id":"X2","man":"O3","coverage":"manual","manualPos":{"x":14,"y":28}},{"id":"X3","man":"O2","coverage":"manual","manualPos":{"x":40,"y":25}},{"id":"X4","man":"O5","coverage":"manual","manualPos":{"x":18,"y":12}},{"id":"X5","man":"O4","coverage":"manual","manualPos":{"x":34,"y":11}}],"ballHolder":"O2","lines":[{"id":"rest2","type":"pass","color":"offense","points":[{"x":43,"y":22},{"x":46,"y":5}]}],"note":"Ball goes to the wing. The wing defender stays tight, the point slides over."},{"offense":[{"id":"O1","pos":{"x":25,"y":40}},{"id":"O2","pos":{"x":43,"y":22}},{"id":"O3","pos":{"x":7,"y":22}},{"id":"O4","pos":{"x":46,"y":5}},{"id":"O5","pos":{"x":4,"y":5}}],"defense":[{"id":"X1","man":"O1","coverage":"manual","manualPos":{"x":32,"y":28}},{"id":"X2","man":"O3","coverage":"manual","manualPos":{"x":22,"y":20}},{"id":"X3","man":"O2","coverage":"manual","manualPos":{"x":42.5,"y":10}},{"id":"X4","man":"O5","coverage":"manual","manualPos":{"x":20,"y":8}},{"id":"X5","man":"O4","coverage":"manual","manualPos":{"x":42.5,"y":2.5}}],"ballHolder":"O4","lines":[],"note":"Ball in the corner: the wing and the baseline defender close the trap. Do not dribble into it - pass out early."}]},{"id":"rest-d-221","section":"defense_half","title":"2-2-1 half court: open three-point line, 2v1 on the back defender","caption":"","frames":[{"offense":[{"id":"O1","pos":{"x":25,"y":45}},{"id":"O2","pos":{"x":42,"y":21}},{"id":"O3","pos":{"x":8,"y":21}},{"id":"O4","pos":{"x":28,"y":19}},{"id":"O5","pos":{"x":11,"y":6}}],"defense":[{"id":"X1","man":"O1","coverage":"manual","manualPos":{"x":19,"y":38}},{"id":"X2","man":"O3","coverage":"manual","manualPos":{"x":31,"y":38}},{"id":"X3","man":"O5","coverage":"manual","manualPos":{"x":12,"y":30}},{"id":"X4","man":"O2","coverage":"manual","manualPos":{"x":38,"y":30}},{"id":"X5","man":"O4","coverage":"manual","manualPos":{"x":25,"y":13}}],"ballHolder":"O1","lines":[{"id":"rest3","type":"pass","color":"offense","points":[{"x":25,"y":45},{"x":42,"y":21}]}],"note":"Fully extended: nobody is on the three-point line, so the wing pass is easy."},{"offense":[{"id":"O1","pos":{"x":25,"y":45}},{"id":"O2","pos":{"x":42,"y":21}},{"id":"O3","pos":{"x":8,"y":21}},{"id":"O4","pos":{"x":28,"y":19}},{"id":"O5","pos":{"x":